                                 prime=cls.PRIME, generator=3, h=5)
        proof = prove_region(xc, yc, 40, 60, xr, yr, region, b"ctx",
                             randbelow=counter_randbelow())
        return RegionProofBundle(xc, yc, region, b"ctx", proof)

    @classmethod
    def region_wide(cls):
        region = Region(0, 255, -2048, 2047)
        xc, xr = pedersen_commit(40, 0, 255, blinding=1234,
                                 prime=cls.PRIME, generator=3, h=5)
        yc, yr = pedersen_commit(60, -2048, 2047, blinding=4321,
                                 prime=cls.PRIME, generator=3, h=5)
        proof = prove_region_wide(xc, yc, 40, 60, xr, yr, region, b"wide-ctx",
                                  randbelow=counter_randbelow())
        return RegionProofBundle(xc, yc, region, b"wide-ctx", proof)

    @classmethod
    def region_neg_empty(cls):
        region = Region(-100, -50, -30, -10)
        xc, xr = pedersen_commit(-75, -100, -50, blinding=1234,
                                 prime=cls.PRIME, generator=3, h=5)
        yc, yr = pedersen_commit(-20, -30, -10, blinding=4321,
                                 prime=cls.PRIME, generator=3, h=5)
        proof = prove_region(xc, yc, -75, -20, xr, yr, region, b"",
                             randbelow=counter_randbelow())
        return RegionProofBundle(xc, yc, region, b"", proof)

    @classmethod
    def region_bigints(cls):
        p255 = 2**255 - 19
        huge = 10**40
        xc = PedersenCommitment(element=1, lower=-huge, upper=-huge, prime=p255,
                                generator=3, h=pow(3, 2, p255))
        yc = PedersenCommitment(element=1, lower=1 << 300,
                                upper=(1 << 300) + 1, prime=p255,
                                generator=3, h=pow(3, 2, p255))
        region = Region(-huge, -huge, 1 << 300, (1 << 300) + 1)
        proof = RegionProof(RangeProof((1,), (0,), (0,)),
                            RangeProof((1,), (0,), (0,)))
        return RegionProofBundle(xc, yc, region, b"big", proof)

    @classmethod
    def polygon_triangle(cls):
        poly = ConvexPolygonRegion(((0, 0), (4, 0), (0, 4)))
        xc, xr = pedersen_commit(1, poly.min_x, poly.max_x, blinding=1234)
        yc, yr = pedersen_commit(2, poly.min_y, poly.max_y, blinding=4321)
        proof = prove_convex_polygon(xc, yc, 1, 2, xr, yr, poly, b"ctx",
                                     randbelow=DetRand())
        return ConvexPolygonProofBundle(xc, yc, poly, b"ctx", proof)

    @classmethod
    def polygon_pentagon(cls):
        poly = ConvexPolygonRegion(((-5, -5), (5, -5), (8, 0), (5, 5), (-5, 5)))
        xc, xr = pedersen_commit(0, poly.min_x, poly.max_x, blinding=1234)
        yc, yr = pedersen_commit(0, poly.min_y, poly.max_y, blinding=4321)
        proof = prove_convex_polygon(xc, yc, 0, 0, xr, yr, poly, b"pentagon",
                                     randbelow=DetRand())
        return ConvexPolygonProofBundle(xc, yc, poly, b"pentagon", proof)

    @classmethod
    def polygon_bigints_bincontext(cls):
        p255 = 2**255 - 19
        huge = 10**40
        xc = PedersenCommitment(element=1, lower=-huge, upper=huge, prime=p255,
                                generator=3, h=pow(3, 2, p255))
        yc = PedersenCommitment(element=1, lower=-huge, upper=huge, prime=p255,
                                generator=3, h=pow(3, 2, p255))
        poly = ConvexPolygonRegion(((-huge, -huge), (huge, -huge), (0, huge)))
        proof = ConvexPolygonRegionProof(
            RangeProof((1,), (0,), (0,)),
            RangeProof((1,), (0,), (0,)),
            tuple(WideRangeProof((1,), ((0, 0),), ((0, 0),)) for _ in range(3)),
        )
        return ConvexPolygonProofBundle(xc, yc, poly, b"\x00\xff\x00binary", proof)

    @classmethod
    def _merkle(cls, leaves, indices):
        proof = prove_multi_inclusion(leaves, indices)
        entries = tuple((i, leaves[i]) for i in indices)
        return MerkleMultiProofBundle(merkle_root(leaves), proof, entries)

    @classmethod
    def merkle_valid(cls):
        leaves = [b"alpha", b"beta", b"gamma", b"delta", b"epsilon"]
        return cls._merkle(leaves, (1, 3))

    @classmethod
    def merkle_single(cls):
        return cls._merkle([b"only"], (0,))

    @classmethod
    def merkle_full8_zeroleaves(cls):
        leaves = [bytes([i, 0, 255 - i]) + f"-{i}".encode() for i in range(8)]
        return cls._merkle(leaves, tuple(range(8)))

    @classmethod
    def merkle_dup_index(cls):
        leaves = [b"alpha", b"beta", b"gamma", b"delta", b"epsilon"]
        root = merkle_root(leaves)
        return MerkleMultiProofBundle(
            root, MerkleMultiProof(5, (1, 1), ()),
            ((1, b"beta"), (1, b"beta")),
        )

    @classmethod
    def merkle_neg_index(cls):
        leaves = [b"alpha", b"beta", b"gamma", b"delta", b"epsilon"]
        root = merkle_root(leaves)
        entries = ((1, leaves[1]), (3, leaves[3]))
        return MerkleMultiProofBundle(
            root, MerkleMultiProof(5, (-1, 3), ()), entries
        )

    @classmethod
    def merkle_empty_entries(cls):
        leaves = [b"alpha", b"beta", b"gamma", b"delta", b"epsilon"]
        root = merkle_root(leaves)
        proof = prove_multi_inclusion(leaves, (1, 3))
        return MerkleMultiProofBundle(root, proof, ())


# (golden key, builder, decoder, encoder, verifier, expected verdict)
_REGION_CASES = (
    "region_narrow",
    "region_wide",
    "region_neg_empty",
    "region_bigints",
)
_POLYGON_CASES = (
    "polygon_triangle",
    "polygon_pentagon",
    "polygon_bigints_bincontext",
)
_MERKLE_CASES = (
    "merkle_valid",
    "merkle_single",
    "merkle_full8_zeroleaves",
    "merkle_dup_index",
    "merkle_neg_index",
    "merkle_empty_entries",
)
_TRUE_CASES = {
    "region_narrow", "region_wide", "region_neg_empty",
    "polygon_triangle", "polygon_pentagon",
    "merkle_valid", "merkle_single", "merkle_full8_zeroleaves",
}
_DECODERS = {
    "region": decode_region_proof_bundle,
    "polygon": decode_convex_polygon_proof_bundle,
    "merkle": decode_merkle_multi_proof_bundle,
}
_ENCODERS = {
    "region": encode_region_proof_bundle,
    "polygon": encode_convex_polygon_proof_bundle,
    "merkle": encode_merkle_multi_proof_bundle,
}
_VERIFIERS = {
    "region": verify_region_proof_bundle,
    "polygon": verify_convex_polygon_proof_bundle,
    "merkle": verify_merkle_multi_proof_bundle,
}


def _family(key):
    if key in _REGION_CASES:
        return "region"
    if key in _POLYGON_CASES:
        return "polygon"
    return "merkle"


class GoldenByteCompatTest(unittest.TestCase):
    """Old fixed bytes must survive the refactor byte-for-byte."""

    def _case(self, key):
        family = _family(key)
        bundle = getattr(BundleBuilders, key)()
        old_bytes = GOLDEN[key]
        return family, bundle, old_bytes

    def test_headers_preserved(self):
        self.assertEqual(GOLDEN["region_narrow"][:6], b"zrgn" + bytes((1, 1)))
        self.assertEqual(GOLDEN["region_wide"][:6], b"zrgn" + bytes((1, 2)))
        self.assertEqual(GOLDEN["polygon_triangle"][:5], b"zrgp" + bytes((1,)))
        self.assertEqual(GOLDEN["merkle_valid"][:5], b"zmmp" + bytes((1,)))

    def test_new_encoder_emits_old_bytes(self):
        for key in _REGION_CASES + _POLYGON_CASES + _MERKLE_CASES:
            with self.subTest(key=key):
                family, bundle, old_bytes = self._case(key)
                self.assertEqual(_ENCODERS[family](bundle), old_bytes)

    def test_old_bytes_decode_to_equal_bundle(self):
        for key in _REGION_CASES + _POLYGON_CASES + _MERKLE_CASES:
            with self.subTest(key=key):
                family, bundle, old_bytes = self._case(key)
                decoded = _DECODERS[family](old_bytes)
                self.assertEqual(decoded, bundle)
                # nested tuple structure is genuinely rebuilt
                self.assertIsInstance(decoded, type(bundle))

    def test_reencoding_decoded_old_bytes_is_identical(self):
        for key in _REGION_CASES + _POLYGON_CASES + _MERKLE_CASES:
            with self.subTest(key=key):
                family, _, old_bytes = self._case(key)
                decoded = _DECODERS[family](old_bytes)
                self.assertEqual(_ENCODERS[family](decoded), old_bytes)

    def test_verification_verdict_preserved(self):
        for key in _REGION_CASES + _POLYGON_CASES + _MERKLE_CASES:
            with self.subTest(key=key):
                family, _, old_bytes = self._case(key)
                decoded = _DECODERS[family](old_bytes)
                expected = key in _TRUE_CASES
                self.assertIs(_VERIFIERS[family](decoded), expected)

    def test_proof_type_tags_remain_distinct(self):
        self.assertIsInstance(
            _DECODERS["region"](GOLDEN["region_narrow"]).proof, RegionProof
        )
        self.assertIsInstance(
            _DECODERS["region"](GOLDEN["region_wide"]).proof, RegionWideProof
        )

    def test_polygon_rotation_and_reversal_encode_to_old_bytes(self):
        bundle = BundleBuilders.polygon_triangle()
        old_bytes = GOLDEN["polygon_triangle"]
        canonical = bundle.polygon
        for vertices in (
            tuple(canonical.vertices[1:] + canonical.vertices[:1]),
            tuple(reversed(canonical.vertices)),
        ):
            same_region = ConvexPolygonRegion(vertices)
            other = ConvexPolygonProofBundle(
                bundle.x_commitment, bundle.y_commitment, same_region,
                bundle.context, bundle.proof,
            )
            self.assertEqual(
                encode_convex_polygon_proof_bundle(other), old_bytes
            )
            self.assertEqual(
                decode_convex_polygon_proof_bundle(old_bytes), other
            )

    def test_merkle_preserves_index_order_and_zero_byte_leaves(self):
        decoded = decode_merkle_multi_proof_bundle(
            GOLDEN["merkle_full8_zeroleaves"]
        )
        self.assertEqual(decoded.proof.indices, tuple(range(8)))
        for i in range(8):
            self.assertEqual(decoded.entries[i][0], i)
            self.assertEqual(decoded.entries[i][1], bytes([i, 0, 255 - i]) + f"-{i}".encode())
            self.assertIn(0, decoded.entries[i][1])

    def test_empty_context_and_negative_bounds_preserved(self):
        decoded = decode_region_proof_bundle(GOLDEN["region_neg_empty"])
        self.assertEqual(decoded.context, b"")
        self.assertEqual(decoded.region.min_x, -100)


class GoldenCorruptionTest(unittest.TestCase):
    """Format-invalid mutations of fixed bytes must raise, never return partial."""

    def _all_raws(self):
        keys = _REGION_CASES + _POLYGON_CASES + _MERKLE_CASES
        return ((key, _family(key), GOLDEN[key]) for key in keys)

    def test_non_bytes_raises_typeerror(self):
        for key, family, raw in self._all_raws():
            decode = _DECODERS[family]
            for bad in (bytearray(raw), memoryview(raw), str(raw), 7, None, [raw]):
                with self.subTest(key=key, bad=type(bad).__name__):
                    with self.assertRaises(TypeError):
                        decode(bad)

    def test_every_truncation_raises_valueerror(self):
        for key, family, raw in self._all_raws():
            decode = _DECODERS[family]
            with self.subTest(key=key):
                for cut in range(len(raw)):
                    with self.assertRaises(ValueError):
                        decode(raw[:cut])

    def test_trailing_bytes_raise_valueerror(self):
        for key, family, raw in self._all_raws():
            decode = _DECODERS[family]
            for extra in (b"\x00", b"ab", b"\xff" * 8):
                with self.subTest(key=key):
                    with self.assertRaises(ValueError):
                        decode(raw + extra)
                    with self.assertRaises(ValueError):
                        decode(extra + raw)

    def test_bad_magic_and_version_raise_valueerror(self):
        for key, family, raw in self._all_raws():
            decode = _DECODERS[family]
            with self.subTest(key=key):
                bad_magic = bytearray(raw)
                bad_magic[0] ^= 0xFF
                with self.assertRaises(ValueError):
                    decode(bytes(bad_magic))
                bad_version = bytearray(raw)
                bad_version[4] = 99
                with self.assertRaises(ValueError):
                    decode(bytes(bad_version))

    def test_region_unknown_proof_tag_raises(self):
        raw = bytearray(GOLDEN["region_narrow"])
        raw[5] = 9
        with self.assertRaises(ValueError):
            decode_region_proof_bundle(bytes(raw))

    def test_noncanonical_integer_raises(self):
        # Insert a leading zero magnitude byte into the first framed integer
        # of the region commitment (offset 14), growing both frames.
        raw = bytearray(GOLDEN["region_narrow"])
        int_len = int.from_bytes(raw[14:18], "big")
        raw[6:10] = (int.from_bytes(raw[6:10], "big") + 1).to_bytes(4, "big")
        raw[14:18] = (int_len + 1).to_bytes(4, "big")
        raw[19:19] = b"\x00"  # after sign byte at 18
        with self.assertRaises(ValueError):
            decode_region_proof_bundle(bytes(raw))

    def test_bad_tuple_cardinality_raises(self):
        # Commitment field count 6 -> 5 sits at offset 10 in region_narrow.
        raw = bytearray(GOLDEN["region_narrow"])
        raw[10:14] = (5).to_bytes(4, "big")
        with self.assertRaises(ValueError):
            decode_region_proof_bundle(bytes(raw))
        # Proof field count 3 -> 4 is the first cardinality inside the
        # merkle proof frame of merkle_single.
        mraw = bytearray(GOLDEN["merkle_single"])
        root_len = int.from_bytes(mraw[5:9], "big")
        proof_card_at = 9 + root_len + 4
        mraw[proof_card_at:proof_card_at + 4] = (4).to_bytes(4, "big")
        with self.assertRaises(ValueError):
            decode_merkle_multi_proof_bundle(bytes(mraw))

    def test_envelopes_are_not_cross_decodable(self):
        with self.assertRaises(ValueError):
            decode_region_proof_bundle(GOLDEN["polygon_triangle"])
        with self.assertRaises(ValueError):
            decode_region_proof_bundle(GOLDEN["merkle_valid"])
        with self.assertRaises(ValueError):
            decode_convex_polygon_proof_bundle(GOLDEN["region_narrow"])
        with self.assertRaises(ValueError):
            decode_merkle_multi_proof_bundle(GOLDEN["region_narrow"])


class GoldenEncodeTypeTest(unittest.TestCase):
    """Encode-side type/value contract is unchanged."""

    def test_region_wrong_types_raise_typeerror(self):
        good = BundleBuilders.region_narrow()
        with self.assertRaises(TypeError):
            encode_region_proof_bundle(object())
        with self.assertRaises(TypeError):
            encode_region_proof_bundle(
                RegionProofBundle(good.x_commitment, good.y_commitment,
                                  good.region, good.context, object())
            )
        with self.assertRaises(TypeError):
            encode_region_proof_bundle(
                RegionProofBundle(good.x_commitment, good.y_commitment,
                                  good.region, 1, good.proof)
            )

    def test_region_forged_inverted_region_raises_valueerror(self):
        good = BundleBuilders.region_narrow()
        forged = object.__new__(Region)
        for name, value in (
            ("min_x", 101), ("max_x", 100), ("min_y", 0), ("max_y", 100)
        ):
            object.__setattr__(forged, name, value)
        object.__setattr__(good, "region", forged)
        with self.assertRaises(ValueError):
            encode_region_proof_bundle(good)

    def test_merkle_wrong_types_raise_typeerror(self):
        good = BundleBuilders.merkle_valid()
        with self.assertRaises(TypeError):
            encode_merkle_multi_proof_bundle(object())
        with self.assertRaises(TypeError):
            encode_merkle_multi_proof_bundle(
                MerkleMultiProofBundle("not-bytes", good.proof, good.entries)
            )
        with self.assertRaises(TypeError):
            encode_merkle_multi_proof_bundle(
                MerkleMultiProofBundle(good.root, good.proof, list(good.entries))
            )

    def test_polygon_wrong_types_raise_typeerror(self):
        good = BundleBuilders.polygon_triangle()
        with self.assertRaises(TypeError):
            encode_convex_polygon_proof_bundle(object())
        with self.assertRaises(TypeError):
            encode_convex_polygon_proof_bundle(
                ConvexPolygonProofBundle(good.x_commitment, good.y_commitment,
                                         good.polygon, good.context, object())
            )


class DecodableButInvalidTest(unittest.TestCase):
    """Format-valid bundles that verification must reject, and vice versa."""

    def test_false_merkle_cases_round_trip_and_fail(self):
        for key in ("merkle_dup_index", "merkle_neg_index",
                    "merkle_empty_entries"):
            with self.subTest(key=key):
                bundle = getattr(BundleBuilders, key)()
                raw = encode_merkle_multi_proof_bundle(bundle)
                self.assertEqual(raw, GOLDEN[key])
                decoded = decode_merkle_multi_proof_bundle(raw)
                self.assertEqual(decoded, bundle)
                self.assertFalse(verify_merkle_multi_proof_bundle(decoded))

    def test_bigint_envelopes_decode_but_do_not_verify(self):
        for key, enc, dec, ver in (
            ("region_bigints", encode_region_proof_bundle,
             decode_region_proof_bundle, verify_region_proof_bundle),
            ("polygon_bigints_bincontext", encode_convex_polygon_proof_bundle,
             decode_convex_polygon_proof_bundle,
             verify_convex_polygon_proof_bundle),
        ):
            with self.subTest(key=key):
                bundle = getattr(BundleBuilders, key)()
                raw = enc(bundle)
                self.assertEqual(raw, GOLDEN[key])
                self.assertFalse(ver(dec(raw)))


